class DType(Enum):
    FP32 = ("fp32", 4)
    FP16 = ("fp16", 2)
    BF16 = ("bf16", 2)
    INT8 = ("int8", 1)
    INT32 = ("int32", 4)
    INT64 = ("int64", 8)
    BOOL = ("bool", 1)

    def __init__(self, alias: str, itemsize: int):
        self._alias = alias
        self._itemsize = itemsize

    @property
    def itemsize(self) -> int:
        return self._itemsize

    @classmethod
    def from_str(cls, name: str) -> "DType":
        for member in cls:
            if member._alias == name:
                return member
        raise ValueError(f"Unknown dtype string: {name}")


class StreamKind(IntEnum):
    COMPUTE = 0
    COMM = 1
    PREFETCH = 2


class TensorRole(Enum):
    INPUT = "INPUT"
    WEIGHT = "WEIGHT"
    ACTIVATION = "ACTIVATION"
    OUTPUT = "OUTPUT"


@dataclass(frozen=True, slots=True)
class TensorSpec:
    name: str
    shape: Tuple[int, ...]
    dtype: DType
    role: TensorRole

    @property
    def numel(self) -> int:
        n = 1
        for d in self.shape:
            if d <= 0:
                raise ValueError(f"Invalid shape dimension in {self.name}: {d}")
            n *= d
        return n

    @property
    def raw_bytes(self) -> int:
        return self.numel * self.dtype.itemsize

    @property
    def aligned_bytes(self) -> int:
        return ((self.raw_bytes + 511) // 512) * 512


